def parse_minutes(raw_value):
    values = [part.strip() for part in raw_value.split(",") if part.strip()]
    if not values:
        raise ValueError("Enter at least one session.")
    minutes = [float(value) for value in values]
    if any(value < 0 for value in minutes):
        raise ValueError("Minutes cannot be negative.")
    return minutes

def hours_from_minutes(values):
    return sum(values) / 60


def test_hours_from_minutes():
    assert hours_from_minutes([30, 45, 15]) == 1.5
